{
    uint32_t now, last, lease, ramp;
    int32_t setpoint;
    while (scanf("%" SCNu32 " %" SCNu32 " %" SCNu32 " %" SCNu32 " %" SCNd32,
                 &now, &last, &lease, &ramp, &setpoint) == 5) {
